export type ServerFunctionRequest = {
    type: "request";
    id: string;
    instance: string;
    source: Request;
    time: number;
};
export type ServerFunctionResponse = {
    type: "response";
    id: string;
    instance: string;
    source: Response;
    time: number;
};
export type ServerFunctionCall = ServerFunctionRequest | ServerFunctionResponse;
export type ServerFunctionCallListener = (event: ServerFunctionCall) => void;
export declare function captureServerFunctionCall(listener: ServerFunctionCallListener): () => void;
export declare function pushRequest(id: string, instance: string, source: Request): void;
export declare function pushResponse(id: string, instance: string, source: Response): void;
